// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/settings/SetupParts.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * The setup steps' building blocks, ported from the app's src/tour/SetupSteps.tsx:
 * the status pill, a setup row, the small buttons, this machine's health,
 * the requirements and the coding agents found. First-launch setup
 * (SetupScreen) and Settings → Security (SetupSettings) both render them.
 * The demo Mac is set up: Homebrew, Node.js and tmux installed, the agent
 * healthy, and three coding agents found.
 */
import type { ReactNode } from "react";
import { Beer, Check, ChevronDown, Hexagon, Laptop, Loader2, SquareTerminal, type LucideIcon } from "lucide-react";
import { AgentMark } from "../../home/AppUI";
import { AGENTS, type AgentId } from "../../home/agents";

export type Tone = "ok" | "busy" | "action" | "fail" | "neutral";

export function Pill({ tone, children }: { tone: Tone; children: ReactNode }) {
  return (
    <span className={`tour-pill tour-pill-${tone}`}>
      {tone === "busy" ? <Loader2 size={11} className="sw-spin" aria-hidden="true" /> : null}
      {children}
    </span>
  );
}

export function SetupRow({
  icon: Icon,
  label,
  detail,
  pill,
  action,
}: {
  icon: LucideIcon;
  label: string;
  detail?: ReactNode;
  pill: { tone: Tone; text: string };
  action?: ReactNode;
}) {
  return (
    <li className="tour-row">
      <span className="tour-row-icon" aria-hidden="true">
        <Icon size={15} strokeWidth={1.9} />
      </span>
      <div className="tour-row-copy">
        <span className="tour-row-label">{label}</span>
        {detail ? <span className="tour-row-detail">{detail}</span> : null}
      </div>
      <div className="tour-row-side">
        <Pill tone={pill.tone}>{pill.text}</Pill>
        {action}
      </div>
    </li>
  );
}

export function SmallButton({ primary = false, icon: Icon, children }: { primary?: boolean; icon?: LucideIcon; children: ReactNode }) {
  return (
    <button type="button" className={`btn btn-sm ${primary ? "btn-accent" : ""}`}>
      {Icon ? <Icon size={12} aria-hidden="true" /> : null}
      {children}
    </button>
  );
}

/** SetupHealth: this Mac's agent, storage and terminal backend, all healthy (details folded). */
export function SetupHealth() {
  return (
    <div className="tour-welcome">
      <div className="tour-health ">
        <div className="tour-health-summary">
          <span className="tour-row-icon" aria-hidden="true">
            <Laptop size={15} strokeWidth={1.9} />
          </span>
          <div className="tour-row-copy">
            <span className="tour-row-label">This Mac is ready</span>
            <span className="tour-row-detail">Agent, storage and terminal backend are working.</span>
          </div>
          <div className="tour-row-side">
            <Pill tone="ok">Ready</Pill>
            <button type="button" className="tour-disclosure" aria-expanded={false} aria-label="Health details">
              <ChevronDown size={14} aria-hidden="true" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

/* The coding agents found on the login PATH (setup_status in the app's
   src-tauri/src/setup.rs reports each one's path); the rest are missing. */
const FOUND: { id: AgentId; path: string }[] = [
  { id: "claude", path: "/opt/homebrew/bin/claude" },
  { id: "codex", path: "/opt/homebrew/bin/codex" },
  { id: "opencode", path: "/opt/homebrew/bin/opencode" },
];

/** CodingAgents: the agents found as chips; the missing ones fold under "Not installed". */
function CodingAgents() {
  // The catalog in the app's order, tier 1 first (agentInstallState).
  const agents = [...AGENTS].sort((a, b) => a.tier - b.tier);
  const installed = agents.flatMap((agent) => {
    const found = FOUND.find((item) => item.id === agent.id);
    return found ? [{ agent, path: found.path }] : [];
  });
  const missing = agents.length - installed.length;
  return (
    <section className="tour-group" aria-label="Coding agents">
      <div className="tour-group-head">
        <span className="tour-group-title">Coding agents</span>
        <span className="tour-group-meta">
          optional · {installed.length} of {agents.length} installed
        </span>
      </div>
      <div className="tour-chips">
        {installed.map(({ agent, path }) => (
          <span key={agent.id} className="tour-chip is-found" title={path}>
            <Check size={11} aria-hidden="true" />
            <AgentMark agent={agent.id} size={12} />
            {agent.label}
            <span className="tour-chip-state">found</span>
          </span>
        ))}
      </div>
      <details className="tour-agent-missing">
        <summary>Not installed ({missing})</summary>
      </details>
    </section>
  );
}

/** SetupRequirements on a Mac with everything installed by Homebrew. */
export function SetupRequirements() {
  return (
    <div className="tour-stack">
      <ul className="tour-list">
        <SetupRow icon={Beer} label="Homebrew" detail="/opt/homebrew/bin/brew" pill={{ tone: "ok", text: "Ready" }} />
        <SetupRow icon={Hexagon} label="Node.js" detail="/opt/homebrew/bin/node" pill={{ tone: "ok", text: "Ready" }} />
        <SetupRow icon={SquareTerminal} label="tmux" detail="/opt/homebrew/bin/tmux" pill={{ tone: "ok", text: "Ready" }} />
      </ul>
      <CodingAgents />
    </div>
  );
}
